import type { HttpContext } from '@adonisjs/core/http'
import env from '#start/env'
import { appPath } from '#config/base_path'

/**
 * Web app manifest, served dynamically so an installed instance carries its own
 * APP_NAME and the visitor's locale. The icon set itself is generated by
 * `npm run generate:app-icons`.
 */
export default class ManifestController {
  async index({ i18n, response }: HttpContext) {
    const appName = env.get('APP_NAME', 'Fridgora')

    response.header('content-type', 'application/manifest+json; charset=utf-8')
    response.header('cache-control', 'public, max-age=3600')

    return {
      id: appPath('/'),
      name: appName,
      short_name: appName,
      lang: i18n?.locale ?? 'cs',
      start_url: appPath('/'),
      scope: appPath('/'),
      display: 'standalone',
      background_color: '#09090b',
      theme_color: '#09090b',
      icons: [
        { src: appPath('/favicon.svg'), sizes: 'any', type: 'image/svg+xml', purpose: 'any' },
        { src: appPath('/icon-192.png'), sizes: '192x192', type: 'image/png', purpose: 'any' },
        { src: appPath('/icon-512.png'), sizes: '512x512', type: 'image/png', purpose: 'any' },
        {
          src: appPath('/icon-maskable-512.png'),
          sizes: '512x512',
          type: 'image/png',
          purpose: 'maskable',
        },
      ],
    }
  }
}
